<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/../config/mailer.php';$db=db();$id=(int)($_GET['id']??$_POST['id']??0);$s=$db->prepare('SELECT p.*,l.name client_name,l.email FROM proposals p JOIN leads l ON l.id=p.lead_id WHERE p.id=? LIMIT 1');$s->execute([$id]);$p=$s->fetch();if(!$p)exit('Proposal not found.');$items=$db->prepare('SELECT * FROM proposal_items WHERE proposal_id=? ORDER BY sort_order,id');$items->execute([$id]);$items=$items->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!filter_var($p['email'],FILTER_VALIDATE_EMAIL)){$error='Client does not have a valid email address.';}else{$url=(defined('APP_URL')?rtrim(APP_URL,'/'):'http://localhost/distinguished-web-services').'/admin/proposal-view.php?token='.$p['public_token'];$subject='Proposal '.$p['proposal_number'].' — '.$p['title'];$rows='';foreach($items as $i)$rows.='<tr><td>'.htmlspecialchars($i['description'],ENT_QUOTES,'UTF-8').'</td><td>'.number_format((float)$i['quantity'],2).'</td><td>'.htmlspecialchars($p['currency'],ENT_QUOTES,'UTF-8').' '.number_format((float)$i['amount'],2).'</td></tr>';$body='<div style="font-family:Arial,sans-serif;max-width:700px"><h2>Distinguished Web Services</h2><p>Hello '.htmlspecialchars($p['client_name'],ENT_QUOTES,'UTF-8').',</p><p>Thank you for the opportunity to work with you. Please review your proposal below.</p><table cellpadding="10" cellspacing="0" border="1" style="border-collapse:collapse;width:100%"><tr><th>Description</th><th>Qty</th><th>Amount</th></tr>'.$rows.'<tr><th colspan="2" style="text-align:right">Total</th><th>'.$esc($p['currency']).' '.number_format((float)$p['total'],2).'</th></tr></table><p><a href="'.htmlspecialchars($url,ENT_QUOTES,'UTF-8').'" style="display:inline-block;padding:12px 18px;background:#111;color:#fff;text-decoration:none">View & Respond to Proposal</a></p><p>Regards,<br>Distinguished Web Services</p></div>';$r=send_smtp_email($p['email'],$subject,$body);if($r['success']){$db->prepare("UPDATE proposals SET status='sent',sent_at=NOW() WHERE id=? AND status IN ('draft','sent')")->execute([$id]);$db->prepare("INSERT INTO proposal_events(proposal_id,event_type,ip_address,user_agent) VALUES(?,?,?,?)")->execute([$id,'sent',$_SERVER['REMOTE_ADDR']??null,substr($_SERVER['HTTP_USER_AGENT']??'',0,500)]);$db->prepare("INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)")->execute([$p['lead_id'],'proposal','Proposal sent',$p['proposal_number'].' was emailed to '.$p['email'].'.']);header('Location: proposals.php?sent=1');exit;}else{$error='Email failed: '.$r['error'];}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Send Proposal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:700px"><div class="card border-0 shadow-sm p-4"><h1 class="h3">Send Proposal</h1><p>Send <strong><?=$esc($p['proposal_number'])?></strong> to <strong><?=$esc($p['email'])?></strong>.</p><?php if($error):?><div class="alert alert-danger"><?=$esc($error)?></div><?php endif;?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-dark">Send Proposal</button><a href="proposal-form.php?id=<?=$id?>" class="btn btn-outline-secondary ms-2">Back</a></form></div></main></body></html>